// The parity suite: the TypeScript solver must return exactly what the Scala
// solver returns, for every puzzle input the repo ships.
//
// __fixtures__/puzzles.json holds, for each api/input/*.in file, the board the
// original Scala solver produced. Those expected values were generated by
// running the Scala solver itself (see web/src/solver/README.md), not by
// running the port, so agreement here is evidence and not a tautology.
//
// Every accepted board is additionally re-checked against the rules of KenKen
// by `validateBoard` below, so a green run means both "same answer as Scala"
// and "that answer is a legal KenKen board".
import puzzlesJson from './__fixtures__/puzzles.json?raw';
import { parseConstraintLine, solveFromAPI } from './KenKenSolver';
import type { Operator } from './Operator';

interface Puzzle {
  name: string;
  sourcePuzzle: string | null;
  boardStrings: string[];
  constraintString: string;
  expectedBoardOutput: string | null;
  expectedSolved: boolean;
  expectedSource: string;
  alternativeValidSolution?: string;
  note?: string;
}

const puzzles = JSON.parse(puzzlesJson) as Puzzle[];

// Independent checker: a solved board is legal when every row and column is a
// permutation of 1..N and every cage's cells meet the cage's target.
function validateBoard(boardOutput: string, boardStrings: string[], constraintString: string): string[] {
  const rows = boardOutput.split('\n').map((row) => row.split(' ').map(Number));
  const size = rows.length;
  const problems: string[] = [];
  const expectedValues = Array.from({ length: size }, (_, index) => index + 1).join(',');

  const checkLine = (label: string, values: number[]): void => {
    if ([...values].sort((a, b) => a - b).join(',') !== expectedValues) {
      problems.push(`${label} is not a permutation of 1..${size}: ${values.join(',')}`);
    }
  };

  rows.forEach((row, index) => checkLine(`row ${index}`, row));
  for (let column = 0; column < size; column++) {
    checkLine(`column ${column}`, rows.map((row) => row[column]));
  }

  const cages = new Map<string, { value: number; operator: Operator; cells: number[] }>();
  for (const constraint of parseConstraintLine(constraintString)) {
    cages.set(constraint.name, { value: constraint.value, operator: constraint.operator, cells: [] });
  }
  boardStrings.forEach((line, row) => {
    line.split(' ').forEach((cageName, column) => {
      const cage = cages.get(cageName);
      if (cage === undefined) {
        problems.push(`cell (${row}, ${column}) names unknown cage ${cageName}`);
        return;
      }
      cage.cells.push(rows[row][column]);
    });
  });

  for (const [name, cage] of cages) {
    const values = cage.cells;
    if (values.length === 0) {
      problems.push(`cage ${name} covers no cells`);
      continue;
    }
    const sum = values.reduce((total, value) => total + value, 0);
    const product = values.reduce((total, value) => total * value, 1);
    const largest = Math.max(...values);
    const smallest = Math.min(...values);
    const ok =
      (cage.operator === '+' && sum === cage.value) ||
      (cage.operator === 'x' && product === cage.value) ||
      (cage.operator === '-' && values.length === 2 && largest - smallest === cage.value) ||
      (cage.operator === '/' && values.length === 2 && largest / smallest === cage.value) ||
      (cage.operator === '' && values.length === 1 && values[0] === cage.value);
    if (!ok) {
      problems.push(`cage ${name}${cage.value}${cage.operator} holds ${values.join(',')}`);
    }
  }

  return problems;
}

describe('TypeScript solver vs the original Scala solver', () => {
  it('compares every puzzle the repo ships', () => {
    expect(puzzles).toHaveLength(7);
  });

  it('has oracle-generated expectations, not port-generated ones', () => {
    for (const puzzle of puzzles) {
      expect(puzzle.expectedSource).toBeTruthy();
    }
  });

  describe.each(puzzles.map((puzzle) => [puzzle.name, puzzle] as const))('%s', (_name, puzzle) => {
    const result = solveFromAPI(puzzle.boardStrings, puzzle.constraintString);

    it(`returns the Scala answer (${puzzle.expectedSource})`, () => {
      expect(result.solved).toBe(puzzle.expectedSolved);
      expect(result.boardOutput).toBe(puzzle.expectedBoardOutput);
    });

    it('returns a legal KenKen board when it claims a solution', () => {
      if (!result.solved || result.boardOutput === null) {
        expect(result.cells).toBeNull();
        return;
      }
      expect(validateBoard(result.boardOutput, puzzle.boardStrings, puzzle.constraintString)).toEqual([]);
    });

    if (puzzle.alternativeValidSolution !== undefined) {
      it('accepts the other valid solution of a multi-solution puzzle', () => {
        expect(
          validateBoard(puzzle.alternativeValidSolution as string, puzzle.boardStrings, puzzle.constraintString),
        ).toEqual([]);
      });
    }
  });
});
